BEGIN;INSERT INTO tenants(id,name) VALUES('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','tenant-a'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','tenant-b') ON CONFLICT DO NOTHING;INSERT INTO customers(tenant_id,stripe_customer_id,email) VALUES('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','cus_rls_a','a@example.test'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','cus_rls_b','b@example.test') ON CONFLICT DO NOTHING;SET LOCAL ROLE recovery_app_login;SELECT set_config('app.tenant_id','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);DO $$ DECLARE n int;BEGIN SELECT count(*) INTO n FROM customers WHERE stripe_customer_id IN('cus_rls_a','cus_rls_b');IF n<>1 THEN RAISE EXCEPTION 'RLS read isolation failed';END IF;END $$;DO $$ BEGIN INSERT INTO customers(tenant_id,stripe_customer_id) VALUES('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','cus_rls_cross_write');RAISE EXCEPTION 'cross tenant insert unexpectedly succeeded';EXCEPTION WHEN insufficient_privilege THEN NULL;WHEN check_violation THEN NULL;END $$;ROLLBACK;